// Calendar entries for the wedding: the .ics files, Google and Outlook links.
// All-day by default. With WEDDING.time ('HH:MM', Berlin wall clock) every entry gets the same
// start in UTC and an end 12 hours later, so no VTIMEZONE block is needed.
// Shared by the page (countdown.js), tools/make-ics.mjs and tests/calendar.test.js.
import { compact, nextDay } from './time.js'

const pad = n => String(n).padStart(2, '0')
const EVENT_HOURS = 12

// One static file per language, generated by `npm run make:ics`:
// save-the-date.ics (German) and save-the-date-tr.ics.
export const icsFile = lang => (!lang || lang === 'de' ? 'save-the-date.ics' : `save-the-date-${lang}.ics`)

// RFC 5545 TEXT escaping (3.3.11). Only for TEXT values such as SUMMARY and DESCRIPTION, never for URL.
export const escapeText = s => String(s).replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n')

// RFC 5545 line folding: at most 75 octets per line, continuation lines start with one space.
// Never splits a UTF-8 character.
export function fold(line) {
  const enc = new TextEncoder()
  if (enc.encode(line).length <= 75) return line
  const out = []
  let chunk = ''
  let size = 0
  for (const ch of line) {
    const n = enc.encode(ch).length
    if (size + n > (out.length ? 74 : 75)) { out.push(chunk); chunk = ''; size = 0 }
    chunk += ch
    size += n
  }
  out.push(chunk)
  return out.join('\r\n ')
}

// Wall-clock parts of an instant in `timeZone`.
function partsIn(instant, timeZone) {
  const fmt = new Intl.DateTimeFormat('en-CA', {
    timeZone, year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23',
  })
  const p = Object.fromEntries(fmt.formatToParts(instant).map(x => [x.type, +x.value]))
  return Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second)
}

// UTC instant of `hour:minute` on `date` as read on a wall clock in `timeZone` (DST safe).
export function zonedTime(date, hour, minute, timeZone) {
  const wanted = Date.UTC(date.year, date.month - 1, date.day, hour, minute)
  let guess = wanted
  for (let i = 0; i < 3; i++) {
    const diff = partsIn(new Date(guess), timeZone) - wanted
    if (diff === 0) break
    guess -= diff
  }
  return new Date(guess)
}

// { allDay: true } or { allDay: false, start, end } with UTC Dates.
export function eventTimes(wedding) {
  const m = /^([01]?\d|2[0-3]):([0-5]\d)$/.exec(String(wedding.time ?? '').trim())
  if (!m) return { allDay: true }
  const start = zonedTime(wedding.date, +m[1], +m[2], wedding.timeZone)
  return { allDay: false, start, end: new Date(start.getTime() + EVENT_HOURS * 3600000) }
}

const utcStamp = d => `${d.getUTCFullYear()}${pad(d.getUTCMonth() + 1)}${pad(d.getUTCDate())}T${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}${pad(d.getUTCSeconds())}Z`
const isoUtc = d => d.toISOString().replace(/\.\d{3}Z$/, 'Z')
const isoDate = d => `${d.year}-${pad(d.month)}-${pad(d.day)}`

// The event description, with the site address on its own line once it is known.
export const eventDescription = (wedding, description) => (wedding.siteUrl ? `${description}\n${wedding.siteUrl}` : description)

// Event title and description for one language, straight from a copy catalog ({a} and {b} are the names).
export function eventCopy(catalog, wedding) {
  const vars = { a: wedding.partnerA, b: wedding.partnerB }
  const fill = s => String(s ?? '').replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m))
  return { title: fill(catalog['ics.summary']), description: fill(catalog['ics.description']) }
}

export function buildIcs({ wedding, title, description, now = new Date() }) {
  if (!wedding.calendarUid) throw new Error('WEDDING.calendarUid is required: a fixed id, never built from names')
  const t = eventTimes(wedding)
  const when = t.allDay
    ? [`DTSTART;VALUE=DATE:${compact(wedding.date)}`, `DTEND;VALUE=DATE:${compact(nextDay(wedding.date))}`]
    : [`DTSTART:${utcStamp(t.start)}`, `DTEND:${utcStamp(t.end)}`]
  const lines = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    `PRODID:${escapeText(`-//${wedding.partnerA} und ${wedding.partnerB}//Save the Date//DE`)}`,
    'CALSCALE:GREGORIAN',
    'METHOD:PUBLISH',
    'BEGIN:VEVENT',
    `UID:${wedding.calendarUid}`,
    `DTSTAMP:${utcStamp(now)}`,
    ...when,
    `SUMMARY:${escapeText(title)}`,
    `DESCRIPTION:${escapeText(eventDescription(wedding, description))}`,
    wedding.siteUrl ? `URL:${wedding.siteUrl}` : null,
    'TRANSP:OPAQUE',
    'END:VEVENT',
    'END:VCALENDAR',
  ].filter(Boolean)
  return lines.map(fold).join('\r\n') + '\r\n'
}

export function googleLink({ wedding, title, description }) {
  const t = eventTimes(wedding)
  const q = new URLSearchParams({
    action: 'TEMPLATE',
    text: title,
    dates: t.allDay ? `${compact(wedding.date)}/${compact(nextDay(wedding.date))}` : `${utcStamp(t.start)}/${utcStamp(t.end)}`,
    details: eventDescription(wedding, description),
    ctz: wedding.timeZone,
  })
  return `https://calendar.google.com/calendar/render?${q}`
}

export function outlookLink({ wedding, title, description }) {
  const t = eventTimes(wedding)
  const q = new URLSearchParams({
    path: '/calendar/action/compose',
    rru: 'addevent',
    subject: title,
    body: eventDescription(wedding, description),
    startdt: t.allDay ? isoDate(wedding.date) : isoUtc(t.start),
    enddt: t.allDay ? isoDate(nextDay(wedding.date)) : isoUtc(t.end),
    allday: String(t.allDay),
  })
  // Outlook on the web may show a form-encoded '+' literally in the title, so spaces go out as %20.
  // A real '+' in the text is already %2B here, so this replace cannot touch it.
  return `https://outlook.live.com/calendar/0/deeplink/compose?${q.toString().replace(/\+/g, '%20')}`
}
